class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # month -> {name: size}
        self._files = {}
        # month -> total counted bytes
        self._used = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0")

        files = self._files.setdefault(month, {})
        used = self._used.setdefault(month, 0)

        if name in files:
            # Same name in same month: does not count a second time.
            # Keep accounting consistent; the existing entry's size stands.
            return

        new_used = used + size_bytes
        if new_used > self._limit_bytes:
            raise ValueError("Monthly quota exceeded")

        files[name] = size_bytes
        self._used[month] = new_used

    def delete(self, name: str, month: str) -> None:
        # Deleting does not give back quota in the current month.
        files = self._files.get(month)
        if not files:
            return
        if name in files:
            del files[name]

    def used_bytes(self, month: str) -> int:
        return self._used.get(month, 0)
